"""
Load/save the VPN pre-shared-key file, the SNMP community-string file, and
the logging FTP password file, each kept separate from its structural JSON
(parsed/vpn.json, parsed/snmp.json, parsed/logging.json) so secrets don't
ride along with data that might otherwise get shared, diffed, or attached
somewhere. Same tier as config.yaml: gitignored by name, never auto-synced.
"""
import os
import yaml

SECRETS_HEADER = (
    "PRE-SHARED KEYS -- do not commit this file. It is excluded via "
    ".gitignore by name, same as config.yaml. Generated by parse_asa_config.py; "
    "hand-edit or add entries here for tunnels the parser couldn't extract a key for."
)


def load_vpn_secrets(path):
    if not os.path.exists(path):
        return {}
    with open(path) as f:
        data = yaml.safe_load(f) or {}
    return data.get("tunnels", {}) or {}


def save_vpn_secrets(path, tunnels_by_peer):
    data = {"_comment": SECRETS_HEADER, "tunnels": tunnels_by_peer}
    with open(path, "w") as f:
        yaml.safe_dump(data, f, default_flow_style=False, sort_keys=False)


SNMP_SECRETS_HEADER = (
    "SNMP COMMUNITY STRINGS -- do not commit this file. It is excluded via "
    ".gitignore by name, same as config.yaml and vpn_secrets.yaml. Generated by "
    "parse_asa_config.py; hand-edit or add entries here for hosts the parser "
    "couldn't extract a community for. Keyed by community_key from "
    "parsed/snmp.json (a host's IP, or \"_global\" for a bare `snmp-server "
    "community` statement)."
)


def load_snmp_secrets(path):
    if not os.path.exists(path):
        return {}
    with open(path) as f:
        data = yaml.safe_load(f) or {}
    return data.get("communities", {}) or {}


def save_snmp_secrets(path, communities_by_key):
    data = {"_comment": SNMP_SECRETS_HEADER, "communities": communities_by_key}
    with open(path, "w") as f:
        yaml.safe_dump(data, f, default_flow_style=False, sort_keys=False)


LOGGING_SECRETS_HEADER = (
    "LOGGING FTP PASSWORD -- do not commit this file. It is excluded via "
    ".gitignore by name, same as config.yaml, vpn_secrets.yaml, and "
    "snmp_secrets.yaml. Generated by parse_asa_config.py from ASA's "
    "`logging ftp-server <host> <path> <username> <password>` line."
)


def load_logging_secrets(path):
    if not os.path.exists(path):
        return None
    with open(path) as f:
        data = yaml.safe_load(f) or {}
    return data.get("ftp_password")


def save_logging_secrets(path, ftp_password):
    if not ftp_password:
        return
    data = {"_comment": LOGGING_SECRETS_HEADER, "ftp_password": ftp_password}
    with open(path, "w") as f:
        yaml.safe_dump(data, f, default_flow_style=False, sort_keys=False)
